<?php
require_once __DIR__ . '/includes/functions.php'; $user=require_role(['customer']); $pageTitle='Your orders';
$stmt=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$stmt->execute([$user['id']]);$orders=$stmt->fetchAll();
$stmt=db()->prepare('SELECT r.*,t.table_number FROM reservations r LEFT JOIN restaurant_tables t ON t.id=r.table_id WHERE r.user_id=? ORDER BY r.reservation_date DESC,r.reservation_time DESC LIMIT 30');$stmt->execute([$user['id']]);$reservations=$stmt->fetchAll();
require __DIR__ . '/includes/header.php'; ?>
<section class="page-shell"><div class="page-heading"><span class="eyebrow">THE GOOD STUFF, ON ITS WAY</span><h1>Your <em>orders.</em></h1><p>Keep tabs on the kitchen and find your table requests.</p></div><div class="section-label"><h2>Order history</h2><a class="inline-link" href="index.html#menu">Order something good ↗</a></div><?php if(!$orders): ?><div class="content-card empty-state"><span>✳</span><h3>Your story starts with a good meal.</h3><p>Your orders will show up here once you place one.</p><a class="button button-dark" href="index.html#menu">Browse the menu</a></div><?php else: ?><div class="order-list"><?php foreach($orders as $order): ?><article class="content-card order-card"><div class="order-card-head"><div><span class="eyebrow"><?= e($order['order_number']) ?></span><h3><?= date('M j, Y · g:i A',strtotime($order['created_at'])) ?></h3></div><span class="status-pill status-<?= strtolower($order['status']) ?>"><?= e($order['status']) ?></span></div><div class="order-card-bottom"><b><?= money($order['total']) ?></b><div><a class="button button-outline-dark button-small" href="track.php?id=<?= (int)$order['id'] ?>">Track order</a><button class="button button-dark button-small reorder-btn" data-order="<?= (int)$order['id'] ?>">Reorder</button></div></div></article><?php endforeach; ?></div><?php endif; ?>
<div id="reservations" class="section-label section-spaced"><h2>Table requests</h2><a class="inline-link" href="reserve.php">Book another ↗</a></div><?php if(!$reservations): ?><p class="muted">No table requests yet.</p><?php else: ?><div class="reservation-list"><?php foreach($reservations as $r): ?><article class="content-card reservation-row"><div><span class="eyebrow"><?= date('l, M j, Y',strtotime($r['reservation_date'])) ?></span><h3><?= date('g:i A',strtotime($r['reservation_time'])) ?> · <?= (int)$r['guests'] ?> guests</h3><p><?= $r['table_number'] ? 'Table '.e($r['table_number']) : 'Table to be assigned' ?></p></div><span class="status-pill status-<?= strtolower($r['status']) ?>"><?= e($r['status']) ?></span></article><?php endforeach; ?></div><?php endif; ?></section>
<script>document.addEventListener('click',async e=>{const b=e.target.closest('.reorder-btn');if(!b)return;const old=b.textContent;b.disabled=true;b.textContent='Loading…';try{const res=await fetch('api/reorder.php?id='+encodeURIComponent(b.dataset.order));const data=await res.json();if(!res.ok)throw new Error(data.error||'Could not reorder');let cart=JSON.parse(localStorage.getItem('oliveCart')||'[]');for(const item of data.items){const found=cart.find(x=>Number(x.id)===Number(item.id));if(found)found.quantity=Math.min(20,Number(found.quantity)+Number(item.quantity));else cart.push(item);}localStorage.setItem('oliveCart',JSON.stringify(cart));location.href='cart.php';}catch(err){alert(err.message);b.disabled=false;b.textContent=old;}});</script>
<?php require __DIR__ . '/includes/footer.php'; ?>
